-- 000108_pte_core_bank.up.sql
-- PTE Core bank 1: 10 Write Email and 10 Respond to a Situation, original, tagged PTE Core.
-- Generated by scripts/generate_pte_core_b1.py.

INSERT INTO questions (id, exam_version_id, exam, skill, type_id, type_name, title, prompt, context_passage, audio_transcript, model_answer, prep_time_seconds, time_limit_seconds, points, difficulty, explanation, tags, supported_exams, is_published) VALUES
    ('pte-core-email-001', 'pte-2026-01', 'PTE', 'writing', 'pte-write-email', 'Write Email', 'Building work next door', 'Read the situation below. Then write an email in response.

The flat next to yours is being renovated. For the past two weeks, drilling has started at 7 am, including on Saturdays, and you work night shifts. Write an email to the building manager.

In your email:
• describe the problem and how long it has been going on
• explain how it is affecting you
• suggest a change that would help

Write 50 to 120 words. You have 9 minutes.', NULL, NULL, 'Dear Mr Collins,

I am writing about the renovation in flat 4B, next to mine. For the past two weeks, drilling has begun at 7 am every day, Saturdays included.

I work night shifts at the hospital and usually sleep until early afternoon. Since the work started, I have been getting only three or four hours of sleep, and I am finding it hard to concentrate at work.

Would it be possible to ask the builders to start the noisiest jobs after 10 am, and to stop work on Saturdays? I would be very grateful for your help.

Kind regards,
Priya Sharma', 0, 540, 15, 'medium', 'A formal email to someone in charge: give the facts (where, when, how long), the effect on you, and one clear, reasonable request. Open with ''Dear'' and the name, close with ''Kind regards''.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Write Email']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-email-002', 'pte-2026-01', 'PTE', 'writing', 'pte-write-email', 'Write Email', 'Charged after cancelling a gym membership', 'Read the situation below. Then write an email in response.

You cancelled your gym membership in person last month and were told there would be no more payments. This month, the full monthly fee was taken from your bank account again. Write an email to the gym''s customer services team.

In your email:
• say when and how you cancelled
• explain what has happened since
• say what you want them to do

Write 50 to 120 words. You have 9 minutes.', NULL, NULL, 'Dear Customer Services,

I cancelled my membership (number 20417) at the front desk of your Leeds city centre branch on 3 March. The member of staff told me that my February payment would be the last one.

However, on 1 April the full monthly fee of £39 was taken from my account again. I have not used the gym since I cancelled.

Please refund this payment within the next week and confirm in writing that my membership has been closed, so that no further payments are taken.

Yours faithfully,
Daniel Hughes', 0, 540, 15, 'medium', 'Give reference details (membership number, date, branch), state the problem plainly, and end with a specific request and a time frame. Keep the tone firm but polite.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Write Email']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-email-003', 'pte-2026-01', 'PTE', 'writing', 'pte-write-email', 'Write Email', 'Asking to swap a work shift', 'Read the situation below. Then write an email in response.

Your sister is getting married on a Saturday next month, and you have just seen that you are on the rota to work that day. Write an email to your manager.

In your email:
• explain why you need the day off
• say what you have already done to solve the problem
• offer something in return

Write 50 to 120 words. You have 9 minutes.', NULL, NULL, 'Hi Sarah,

I have just seen the rota for next month, and I am down to work on Saturday the 14th. Unfortunately, that is the day of my sister''s wedding, and I am one of the bridesmaids.

I have already spoken to Tom, and he is happy to work my shift that day if you agree.

In return, I can take his Sunday shift on the 15th, or any other day that suits the team. Please let me know if this is acceptable.

Many thanks,
Aisha', 0, 540, 15, 'medium', 'A semi-formal email to a manager. Explain the reason briefly, show you have found a solution, and offer something in return. A first-name greeting is fine if that is normal at work.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Write Email']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-email-004', 'pte-2026-01', 'PTE', 'writing', 'pte-write-email', 'Write Email', 'Volunteering at a community centre', 'Read the situation below. Then write an email in response.

Your local community centre is looking for volunteers to help with its weekend activities for children. You would like to take part. Write an email to the volunteer coordinator.

In your email:
• introduce yourself and say why you are interested
• describe any useful skills or experience
• say when you are available

Write 50 to 120 words. You have 9 minutes.', NULL, NULL, 'Dear Ms Taylor,

I saw your notice in the library asking for weekend volunteers, and I would like to offer my help. I moved to the area last year, and I would like to get to know the community better.

I have two young children of my own, and in my last job I helped to run a holiday club for primary school pupils. I am also a qualified first aider.

I am free every Saturday morning and on most Sunday afternoons. I would be happy to come in to discuss the role.

Best wishes,
Marco Rossi', 0, 540, 15, 'medium', 'Cover all three bullet points in order: who you are and why, what you can bring, and when you are free. Short paragraphs, one per point, make the email easy to follow.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Write Email']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-email-005', 'pte-2026-01', 'PTE', 'writing', 'pte-write-email', 'Write Email', 'A sofa that has not arrived', 'Read the situation below. Then write an email in response.

You bought a sofa from a furniture shop six weeks ago. The shop promised delivery within three weeks, but it has not arrived, and nobody has answered your phone calls. Write an email to the shop manager.

In your email:
• give the details of your order
• explain what has happened so far
• say what you will do if the problem is not solved

Write 50 to 120 words. You have 9 minutes.', NULL, NULL, 'Dear Sir or Madam,

On 2 May I ordered a grey three-seater sofa from your Bristol shop (order number FS-58811) and paid £640 in full. I was told it would be delivered within three weeks.

Six weeks later, the sofa has still not arrived. I have phoned the shop four times, but each time I was asked to leave a message, and nobody has called me back.

Please let me know a firm delivery date by the end of this week. If I do not hear from you, I will ask for a full refund.

Yours faithfully,
Helen Brooks', 0, 540, 15, 'medium', 'Use ''Dear Sir or Madam'' and ''Yours faithfully'' when you do not know the name. Give the order details, the history of the problem, and the next step you will take.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Write Email']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-email-006', 'pte-2026-01', 'PTE', 'writing', 'pte-write-email', 'Write Email', 'A friend visiting your city', 'Read the situation below. Then write an email in response.

An old friend from school is coming to visit your city for a weekend next month and has asked you for advice. Write an email to your friend.

In your email:
• suggest some places to visit
• give advice about getting around
• suggest a time when you can meet

Write 50 to 120 words. You have 9 minutes.', NULL, NULL, 'Hi Jake,

It''s great news that you''re coming to Edinburgh! You''ll love it.

You should definitely walk up to the castle on your first morning, before it gets busy. After that, Arthur''s Seat is a short hike with amazing views of the whole city.

The city centre is small, so you can walk almost everywhere. If you''re tired, the buses are cheap and run every few minutes.

I finish work at five on Friday, so why don''t we meet for dinner that evening? I know a lovely Italian place near the station.

See you soon,
Tom', 0, 540, 15, 'medium', 'An informal email to a friend: a friendly greeting, contractions and a warm sign-off are suitable. Still answer each bullet point clearly, with one short paragraph each.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Write Email']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-email-007', 'pte-2026-01', 'PTE', 'writing', 'pte-write-email', 'Write Email', 'A school trip and a food allergy', 'Read the situation below. Then write an email in response.

Your eight-year-old son''s class is going on a day trip to a farm next week. Lunch will be provided, and your son is allergic to nuts. Write an email to his class teacher.

In your email:
• confirm that your son will go on the trip
• explain his allergy
• ask about the arrangements for lunch

Write 50 to 120 words. You have 9 minutes.', NULL, NULL, 'Dear Mrs Patel,

Thank you for the letter about next Thursday''s trip to Hill Farm. I am happy for Leo to go, and I have returned the signed form with him today.

As you may know, Leo has a serious nut allergy. Even a small amount can make him very ill, and he carries an adrenaline pen in his school bag.

Could you tell me what will be served for lunch, and whether it is prepared without nuts? If it is easier, I can send Leo with a packed lunch instead.

Kind regards,
Anna Novak', 0, 540, 15, 'medium', 'A polite, clear email to a teacher. Confirm the practical detail first, explain the health issue without exaggerating, and ask a direct question, offering a simple alternative.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Write Email']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-email-008', 'pte-2026-01', 'PTE', 'writing', 'pte-write-email', 'Write Email', 'A laptop bag left on a train', 'Read the situation below. Then write an email in response.

Yesterday evening you left your laptop bag on a train. The laptop has work files on it that you need urgently. Write an email to the train company''s lost property office.

In your email:
• say when and where you lost the bag
• describe the bag and what was in it
• explain how they can contact you

Write 50 to 120 words. You have 9 minutes.', NULL, NULL, 'Dear Lost Property Team,

Yesterday, 12 June, I left my laptop bag on the 18:45 train from Manchester Piccadilly to Sheffield. I was sitting in coach C, and I think I left the bag on the luggage rack above my seat.

The bag is black with a red zip and has a small luggage label with my name on it. Inside is a silver laptop, its charger and a blue notebook.

The laptop has files I need for work this week, so I would be very grateful for a quick reply. You can call me on 07700 900452 at any time.

Yours sincerely,
Omar Haddad', 0, 540, 15, 'medium', 'Precise details make this email useful: the date, train time, route and seat. Describe the item clearly and give contact details. ''Yours sincerely'' follows a named or team greeting.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Write Email']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-email-009', 'pte-2026-01', 'PTE', 'writing', 'pte-write-email', 'Write Email', 'A birthday booking that went wrong', 'Read the situation below. Then write an email in response.

You booked a table for ten people at a restaurant for your mother''s birthday. When you arrived, the restaurant had no record of the booking, and your group had to wait an hour. Write an email to the restaurant manager.

In your email:
• explain what you had arranged
• describe what happened on the night
• say what you expect from the restaurant

Write 50 to 120 words. You have 9 minutes.', NULL, NULL, 'Dear Manager,

Two weeks ago I booked a table for ten people at 7 pm last Saturday to celebrate my mother''s 60th birthday. I booked by phone and received a confirmation text.

When we arrived, the staff told us there was no record of the booking. We waited almost an hour for a table, and two elderly relatives had to stand for most of that time. It spoiled what should have been a special evening.

I would appreciate an explanation of what went wrong, and I think a partial refund of our bill would be fair.

Yours sincerely,
Lucy Chen', 0, 540, 15, 'medium', 'Show that you did everything right (the booking and the confirmation), describe the impact briefly, and ask for something specific. Stay polite even when you are unhappy.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Write Email']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-email-010', 'pte-2026-01', 'PTE', 'writing', 'pte-write-email', 'Write Email', 'Thanking a neighbour for looking after a cat', 'Read the situation below. Then write an email in response.

While you were away on holiday for two weeks, your neighbour fed your cat and watered your plants. Write an email to your neighbour.

In your email:
• thank them for their help
• tell them something about your holiday
• invite them to do something with you

Write 50 to 120 words. You have 9 minutes.', NULL, NULL, 'Dear Margaret,

Thank you so much for looking after Biscuit and the plants while we were away. He looks very happy, and the tomatoes have never looked better!

We had a wonderful time in Portugal. The weather was hot and sunny every day, and we spent most of our time on the beach near Lagos. The children even learned to surf.

To say thank you, we would love you to come round for dinner one evening next week. Would Thursday at seven suit you?

With best wishes,
James and Sophie', 0, 540, 15, 'medium', 'A friendly email to a neighbour can be warm but should still be well organised: thanks, a short holiday news paragraph, and a clear invitation with a suggested day and time.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Write Email']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-rts-001', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A prescription that is not ready', 'You have come to the chemist to collect a prescription for your daughter''s ear infection. The assistant tells you it will not be ready until tomorrow, but your daughter needs to start the medicine today. Speak to the assistant. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You have come to the chemist to collect a prescription for your daughter''s ear infection. The assistant tells you it will not be ready until tomorrow, but your daughter needs to start the medicine today. Speak to the assistant.', 'You have come to the chemist to collect a prescription for your daughter''s ear infection. The assistant tells you it will not be ready until tomorrow, but your daughter needs to start the medicine today. Speak to the assistant.', 'I''m sorry, but my daughter really needs to start these antibiotics today. The doctor said the infection could get worse if we wait. Is there any way you could prepare it this afternoon? I''m happy to wait here or come back later. If that isn''t possible, could you tell me whether another chemist nearby might have it in stock?', 20, 40, 15, 'medium', 'Stay polite but explain why it is urgent, then ask for a solution and offer a fallback. A calm, cooperative tone works better than a complaint.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Respond to a Situation']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-rts-002', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Turning down a wedding invitation', 'A close friend has invited you to her wedding in another city. You have just found out that you must travel abroad for work that weekend and cannot go. You call your friend to tell her. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'A close friend has invited you to her wedding in another city. You have just found out that you must travel abroad for work that weekend and cannot go. You call your friend to tell her.', 'A close friend has invited you to her wedding in another city. You have just found out that you must travel abroad for work that weekend and cannot go. You call your friend to tell her.', 'Hi Emma, it''s me. First of all, thank you so much for the invitation. I was really looking forward to it. Unfortunately, my company has just told me I have to go to a conference in Germany that weekend, and I can''t change it. I''m so sorry to miss your big day. Can I take you both out for dinner when you''re back from your honeymoon?', 20, 40, 15, 'medium', 'With a friend, an informal register is appropriate. Thank her, give the reason, say you are sorry and suggest another way to celebrate.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Respond to a Situation']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-rts-003', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'No heating in a hotel room', 'You have checked into a hotel for three nights. It is a cold evening, and the heater in your room does not work. You go to the reception desk to speak to the receptionist. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You have checked into a hotel for three nights. It is a cold evening, and the heater in your room does not work. You go to the reception desk to speak to the receptionist.', 'You have checked into a hotel for three nights. It is a cold evening, and the heater in your room does not work. You go to the reception desk to speak to the receptionist.', 'Good evening. I''m staying in room 214, and I''m afraid the heater isn''t working. I''ve tried the controls several times, but the room is still very cold. Could you send someone to look at it tonight? If it can''t be fixed quickly, would it be possible to move to another room? I''m here for three nights, so I''d really like to get it sorted.', 20, 40, 15, 'medium', 'Give your room number, describe the problem, and make a clear request with an alternative. A polite, formal register suits a hotel reception.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Respond to a Situation']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-rts-004', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Breaking a colleague''s umbrella', 'This morning a colleague lent you her umbrella because it was raining heavily. On your way back to the office, the wind blew it inside out and broke it. Speak to your colleague. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'This morning a colleague lent you her umbrella because it was raining heavily. On your way back to the office, the wind blew it inside out and broke it. Speak to your colleague.', 'This morning a colleague lent you her umbrella because it was raining heavily. On your way back to the office, the wind blew it inside out and broke it. Speak to your colleague.', 'Hi Rachel, I''m really sorry, but I''ve got some bad news about your umbrella. The wind was so strong on the way back that it blew it inside out, and two of the spokes snapped. I feel terrible because you were kind enough to lend it to me. I''d like to buy you a new one. Could you tell me where you got it, or would you like me to choose one?', 20, 40, 15, 'medium', 'Apologise at the start, explain what happened honestly and offer to put it right. A friendly but sincere tone suits a colleague.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Respond to a Situation']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-rts-005', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Wrong change at the supermarket', 'You have just paid for your shopping with a twenty-pound note. When you check your change, you notice the cashier has given you five pounds too little. Speak to the cashier. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You have just paid for your shopping with a twenty-pound note. When you check your change, you notice the cashier has given you five pounds too little. Speak to the cashier.', 'You have just paid for your shopping with a twenty-pound note. When you check your change, you notice the cashier has given you five pounds too little. Speak to the cashier.', 'Excuse me, I''m sorry to bother you, but I think there''s been a small mistake with my change. My shopping came to eleven pounds forty, and I paid with a twenty-pound note, so I should have eight pounds sixty. But you''ve given me three pounds sixty. Could you check it for me, please? I know it''s busy, so it''s easy to do.', 20, 40, 15, 'medium', 'Point out the error politely without blaming the cashier. Give the exact numbers so the problem is clear, and ask them to check.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Respond to a Situation']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-rts-006', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Running late for a hair appointment', 'You have an appointment at the hairdresser''s at 2 pm. Your bus has broken down, and you will be about twenty minutes late. You phone the salon to speak to the receptionist. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You have an appointment at the hairdresser''s at 2 pm. Your bus has broken down, and you will be about twenty minutes late. You phone the salon to speak to the receptionist.', 'You have an appointment at the hairdresser''s at 2 pm. Your bus has broken down, and you will be about twenty minutes late. You phone the salon to speak to the receptionist.', 'Hello, my name is Kate Morgan, and I have an appointment at two o''clock with Louise. I''m really sorry, but my bus has broken down, and I''m going to be about twenty minutes late. Is it still possible for Louise to see me if I arrive at around twenty past? If not, I completely understand, and I''d be happy to book another time later this week.', 20, 40, 15, 'medium', 'Say who you are and which appointment it is, explain the delay briefly, and ask whether they can still fit you in, offering to rebook if not.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Respond to a Situation']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-rts-007', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Welcoming new neighbours', 'A family has just moved into the house next door to you. You see them carrying boxes from a van and decide to go and introduce yourself. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'A family has just moved into the house next door to you. You see them carrying boxes from a van and decide to go and introduce yourself.', 'A family has just moved into the house next door to you. You see them carrying boxes from a van and decide to go and introduce yourself.', 'Hi there, welcome to the street! I''m Ben, and I live next door at number twelve with my wife and our two boys. It looks like you''ve got a lot to carry. Do you need a hand with any of the heavier boxes? Also, the bins are collected on Tuesday mornings, and there''s a good bakery just around the corner. Let us know if you need anything at all.', 20, 40, 15, 'medium', 'A friendly, informal greeting suits this situation. Introduce yourself, offer practical help and give some useful local information.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Respond to a Situation']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-rts-008', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Checking the bus route', 'You need to get to the city hospital for an appointment, but you are not sure which bus to take. A bus has just stopped, and you speak to the driver before getting on. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You need to get to the city hospital for an appointment, but you are not sure which bus to take. A bus has just stopped, and you speak to the driver before getting on.', 'You need to get to the city hospital for an appointment, but you are not sure which bus to take. A bus has just stopped, and you speak to the driver before getting on.', 'Excuse me, does this bus go to the city hospital? I''ve got an appointment there at half past ten, and I''m not sure which bus I need. If it does, could you tell me which stop is closest to the main entrance, please? And if it doesn''t, could you tell me which number I should take instead? Thank you very much.', 20, 40, 15, 'medium', 'Ask a direct question first, then give the reason and follow-up questions. Keep it short and polite, as the driver is working.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Respond to a Situation']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-rts-009', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Asked to work at the weekend', 'Your manager asks you to work this Saturday because a colleague is ill. You have already booked tickets to take your parents to a concert that day. Reply to your manager. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'Your manager asks you to work this Saturday because a colleague is ill. You have already booked tickets to take your parents to a concert that day. Reply to your manager.', 'Your manager asks you to work this Saturday because a colleague is ill. You have already booked tickets to take your parents to a concert that day. Reply to your manager.', 'I''d really like to help, and I''m sorry to hear about Jenny. The problem is that I''ve already booked concert tickets for my parents on Saturday as a birthday present, and I can''t change the date. But I could stay late on Friday to finish anything urgent, or I could work on Sunday instead if that would help. Would either of those work for you?', 20, 40, 15, 'medium', 'Show that you want to help, explain your reason briefly and offer alternatives. This keeps a polite, professional tone while still saying no.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Respond to a Situation']::text[], ARRAY['PTE']::text[], TRUE),
    ('pte-core-rts-010', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A car park machine that takes no cards', 'You have parked at a shopping centre car park. The ticket machine is not accepting your card, and you have no cash. You go to the car park office to speak to the attendant. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You have parked at a shopping centre car park. The ticket machine is not accepting your card, and you have no cash. You go to the car park office to speak to the attendant.', 'You have parked at a shopping centre car park. The ticket machine is not accepting your card, and you have no cash. You go to the car park office to speak to the attendant.', 'Hello, I''m trying to pay for my parking, but the machine on level two won''t accept my card. I''ve tried it three times, and I also tried a different card, but it keeps saying ''payment declined''. I don''t have any cash with me today. Is there another way I can pay, perhaps here at the office or by phone? I don''t want to get a fine.', 20, 40, 15, 'medium', 'Explain what you tried, why you cannot pay another way, and ask for a practical solution. A clear, polite explanation helps the attendant help you.', ARRAY['PTE', 'Original practice', 'PTE Core', 'Respond to a Situation']::text[], ARRAY['PTE']::text[], TRUE)
ON CONFLICT (id) DO NOTHING;
